-- D1 setup. Safe to run again: data is only seeded if missing.
CREATE TABLE IF NOT EXISTS site_config (id TEXT PRIMARY KEY, body TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('news','social','achievement')), title TEXT NOT NULL, excerpt TEXT DEFAULT '', body TEXT DEFAULT '', image TEXT DEFAULT '', url TEXT DEFAULT '', platform TEXT DEFAULT '', media_type TEXT DEFAULT '', status TEXT NOT NULL CHECK(status IN ('draft','published')) DEFAULT 'draft', published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, external_id TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_content_status_kind ON content(status,kind,published_at DESC);
CREATE TABLE IF NOT EXISTS newsletter_subscribers (email TEXT PRIMARY KEY, consent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TEXT, confirm_hash TEXT, unsubscribe_hash TEXT NOT NULL, revoked_at TEXT, source TEXT NOT NULL DEFAULT 'website');
CREATE INDEX IF NOT EXISTS idx_sub_confirm ON newsletter_subscribers(confirm_hash);
CREATE INDEX IF NOT EXISTS idx_sub_unsub ON newsletter_subscribers(unsubscribe_hash);
CREATE TABLE IF NOT EXISTS admin_audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions (
  session_hash TEXT PRIMARY KEY,
  csrf_hash TEXT NOT NULL,
  actor TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  revoked_at INTEGER
);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_expiry ON admin_sessions(expires_at);
CREATE TABLE IF NOT EXISTS admin_login_attempts (
  attempt_hash TEXT PRIMARY KEY,
  attempts INTEGER NOT NULL,
  window_started_at INTEGER NOT NULL,
  locked_until INTEGER
);
CREATE TABLE IF NOT EXISTS integration_settings (
  provider TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),
  page_id TEXT NOT NULL DEFAULT '',
  page_url TEXT NOT NULL DEFAULT '',
  auto_publish INTEGER NOT NULL DEFAULT 0 CHECK(auto_publish IN (0,1)),
  sync_interval_minutes INTEGER NOT NULL DEFAULT 30,
  last_synced_at TEXT,
  last_status TEXT,
  last_error TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT OR IGNORE INTO integration_settings(provider) VALUES ('facebook');
INSERT OR IGNORE INTO site_config (id,body) VALUES ('main', '{"brand":{"name":"SODANGI 2027","subline":"VISION FOR BAUCHI FEDERAL CONSTITUENCY","logo":"/assets/logo.jpg","wideLogo":"/assets/brand.jpg"},"home":{"eyebrow":"BAUCHI FEDERAL CONSTITUENCY · 2027","headline":"A brighter Bauchi. A greater tomorrow.","lead":"Explore the public service background, policy priorities and community development proposals of Adam Chindo Sodangi.","primaryAction":"Explore the SHARES Agenda","secondaryAction":"Meet Sodangi","portrait":"/assets/portrait.jpg","featuredTitle":"Public service. Practical vision.","featuredText":"A place to examine experience, understand proposals and follow progress."},"about":{"eyebrow":"THE PERSON BEHIND THE VISION","title":"Meet Adam Chindo Sodangi","summary":"A political scientist and civil society advocate with over twenty years of experience in governance, policy advocacy and community development, according to his supplied biography. His work has focused on education, health, nutrition, civil society leadership and institution-building at state, national and international levels.","image":"/assets/sodangi.jpg","portrait":"/assets/portrait.jpg","roles":[{"year":"2010–2026","title":"Executive Director, Muslim Aid Initiative Nigeria (MAIN)","detail":"Led a Bauchi-headquartered non-profit working in health, education, good governance, peaceful coexistence and community capacity building. The supplied biography describes partnerships with government agencies and organisations including USAID, UNICEF and the World Bank."},{"year":"2018–2024","title":"Chairman, Forum of Executive Directors of Civil Society Organisations (CSO-EDF)","detail":"The supplied biography describes leadership of a coalition of more than 50 registered NGOs, CBOs and FBOs working across development sectors, with a stated contribution to employment and community structures."},{"year":"2019","title":"Chairman, Joint Gubernatorial Manifesto Presentation","detail":"Coordinated a public manifesto presentation where major gubernatorial candidates presented their proposals, working with civil society organisations and professional bodies."},{"year":"2020–2023","title":"Board Member, Bauchi State Health Contributory Management Agency","detail":"Represented civil society. The supplied biography attributes enrolment of 53,000 Basic Health Care Provision Fund beneficiaries and groundwork for formal-sector adoption to the agency''s work during this period."},{"year":"2022–2026","title":"Board Member, IMPACT Project","detail":"Served as a civil society representative on a World Bank-supported primary health care programme. The supplied biography cites work on facilities, staff quarters and equipment across 323 BHCPF facilities."},{"year":"2020–2026","title":"National Steering Committee Chairman, SUN CSA Nigeria","detail":"The supplied biography describes coalition expansion from five to nineteen states, nutrition-policy advocacy, budget tracking and regional knowledge exchange."},{"year":"2022–2025","title":"International Representation","detail":"The supplied biography reports civil society engagements across nine countries and participation in the 2025 Nutrition for Growth Summit in Paris, France."}],"sourceNote":"Biography and leadership claims are reproduced from candidate-supplied materials and require independent supporting documents before being described as verified."},"vision":{"eyebrow":"THE SIX-PILLAR FRAMEWORK","title":"The SHARES Agenda","intro":"Six connected priorities focused on security, social services, agriculture, representation, inclusion and sustainable futures.","pillars":[{"letter":"S","title":"Security & Safety","summary":"Peace, community engagement and responsive prevention.","description":"Promote community safety through local vigilance partnerships, peacebuilding and proactive conflict-resolution initiatives.","icon":"shield"},{"letter":"H","title":"Health, Education & Nutrition","summary":"Healthier communities and broader learning opportunities.","description":"Work with critical stakeholders to address out-of-school children, strengthen nutrition security and improve maternal and child health.","icon":"heart"},{"letter":"A","title":"Agricultural Transformation","summary":"Support farmers and strengthen food security.","description":"Support rural farmers'' access to improved techniques, soft loans and agricultural extension services.","icon":"sprout"},{"letter":"R","title":"Representation","summary":"Voice, legislation and accountable engagement.","description":"Represent constituency priorities through motions, proposed laws, legislative oversight and constructive national discussions.","icon":"landmark"},{"letter":"E","title":"Empowerment & Gender Inclusion","summary":"Opportunity for women, young people and entrepreneurs.","description":"Promote women''s economic participation and proposed training in AI, cybersecurity, data analytics, design, software development and related emerging skills.","icon":"users"},{"letter":"S","title":"Secured Futures","summary":"Long-term development and sustainable opportunity.","description":"Pursue sustainable empowerment and practical development partnerships that improve community wellbeing and livelihoods.","icon":"target"}],"manifestoUrl":"/assets/sodangiEng.png","hausaUrl":"/assets/sodangiHausa.png","note":"A policy framework expresses proposals, not guaranteed outcomes. Implementation depends on legislation, partnerships, budgets and public institutions."},"digits":{"eyebrow":"SODANGI DIGITs","title":"Digital Infrastructure & Grassroots Investment Training","intro":"A proposed ward-based training and empowerment programme to equip young people with practical digital skills and encourage local innovation.","status":"Proposed programme — applications are not yet open","cohort":120,"perWard":10,"wards":["Majidadi ''A''","Majidadi ''B''","Makama/Sarki Baki","Zungur/Liman Katagum","Mun/Munsal","Dandango/Yamrat","Birshi/Miri","Kundum/Durum","Kangyare/Turwun","Galambi/Gwaskwaram","Dan''iya Hardo","Dawaki"],"skills":["Digital marketing","Hardware maintenance","Data management","Graphic design","Online entrepreneurship"],"benefits":["Fully sponsored hands-on training for selected participants","Proposed digital tools and connectivity kits for qualifying graduates","Mentorship and ward-based community learning hubs"],"footerNote":"Selection criteria, funding arrangements, programme dates and application details will be announced when officially approved."},"contact":{"heading":"Connect with the campaign information team","intro":"For official updates, programme information and press enquiries, use verified contact details when available.","email":"","phone":"","office":"","facebook":"","instagram":"","tiktok":""},"newsletter":{"title":"Stay informed about Bauchi’s future","subtitle":"Receive official news, policy updates and programme announcements. No spam. Unsubscribe whenever you wish.","popupTitle":"Stay close to the story","popupBody":"Subscribe to receive important updates about the vision, programmes and latest news."},"footer":{"tagline":"Public information, transparent commitments and documented progress.","credit":"SODANGI 2027 Information Platform"},"translations":{"ha":{"brand":{"subline":"MANUFAR MAZABAR TARAYYA TA BAUCHI"},"home":{"eyebrow":"MAZABAR TARAYYA TA BAUCHI · 2027","headline":"Bauchi mai haske. Gobe mai kyau.","lead":"Ku karanta tarihin ayyukan jama’a, manufofi da shirye-shiryen ci gaban al’umma na Adam Chindo Sodangi.","primaryAction":"Binciki Tsarin SHARES","secondaryAction":"San Sodangi","featuredTitle":"Hidimar jama’a. Manufa mai amfani.","featuredText":"Wurin sanin gogewar aiki, fahimtar tsare-tsare da bibiyar ci gaba."},"about":{"eyebrow":"SANIN MUTUMIN DA KE DA MANUFA","title":"Ku san Adam Chindo Sodangi","summary":"Bisa tarihin da aka bayar daga bangaren ɗan takarar, shi masanin kimiyyar siyasa ne kuma mai fafutukar ƙungiyoyin farar hula, wanda yake da gogewar fiye da shekaru ashirin a shugabanci, kare manufofi da ci gaban al’umma. Ayyukansa sun shafi ilimi, lafiya, abinci mai gina jiki, shugabancin ƙungiyoyin farar hula da gina cibiyoyi a matakin jiha, ƙasa da ƙasashen duniya.","sourceNote":"An samo bayanan tarihin rayuwa da matsayai daga takardun da ɗan takarar ya bayar. Ana bukatar hujjoji masu zaman kansu kafin a bayyana su a matsayin waɗanda aka tantance.","roles":[{"year":"2010–2026","title":"Babban Darakta, Muslim Aid Initiative Nigeria (MAIN)","detail":"Ya jagoranci ƙungiya mai zaman kanta da hedkwatarta ke Bauchi, mai aiki a fannoni kamar lafiya, ilimi, shugabanci nagari, zaman lafiya da inganta ƙwarewar al’umma. Tarihin da aka bayar ya ambaci haɗin gwiwa da hukumomin gwamnati da ƙungiyoyi ciki har da USAID, UNICEF da Bankin Duniya."},{"year":"2018–2024","title":"Shugaba, Ƙungiyar Manyan Daraktocin Ƙungiyoyin Farar Hula (CSO-EDF)","detail":"Bisa tarihin da aka bayar, ya jagoranci haɗakar ƙungiyoyin sa-kai sama da 50 da ke aiki a fannoni daban-daban na ci gaba, tare da bayyana gudummawa ga samar da ayyukan yi da ƙarfafa tsarin al’umma."},{"year":"2019","title":"Shugaban Taron Gabatar da Manufofin ’Yan Takarar Gwamna","detail":"Ya jagoranci taron da manyan ’yan takarar gwamna suka gabatar da manufofinsu a bainar jama’a, tare da haɗin gwiwar ƙungiyoyin farar hula da ƙwararru."},{"year":"2020–2023","title":"Mamba na Hukumar Kula da Inshorar Lafiya ta Jihar Bauchi","detail":"Ya wakilci ƙungiyoyin farar hula. Tarihin da aka bayar ya danganta rajistar mutane 53,000 a shirin BHCPF da shirye-shiryen faɗaɗa tsarin da ayyukan hukumar a wannan lokaci."},{"year":"2022–2026","title":"Mamba na Kwamitin Gudanar da Shirin IMPACT","detail":"Ya kasance wakilin ƙungiyoyin farar hula a shirin inganta kiwon lafiya na farko wanda Bankin Duniya ke tallafawa. Tarihin ya ambaci gyaran cibiyoyi, gidajen ma’aikata da samar da kayan aiki ga cibiyoyin BHCPF guda 323."},{"year":"2020–2026","title":"Shugaban Kwamitin Gudanarwa na Ƙasa, SUN CSA Nigeria","detail":"Bisa bayanan da aka bayar, haɗakar ta faɗaɗa ayyuka daga jihohi biyar zuwa goma sha tara, ta kuma yi fafutukar inganta manufofin abinci mai gina jiki, bibiyar kasafin kuɗi da musayar ilimi a yankin."},{"year":"2022–2025","title":"Wakilci a Ƙasashen Duniya","detail":"Tarihin da aka bayar ya ambaci hulɗa da ƙungiyoyin farar hula a ƙasashe tara, da halartar taron Nutrition for Growth na shekarar 2025 a Paris, Faransa."}]},"vision":{"eyebrow":"GINSHIKAI SHIDA NA MANUFA","title":"Tsarin SHARES","intro":"Ginshikai shida masu alaƙa da tsaro, kiwon lafiya da ilimi, noma, wakilci, haɗa kowa da kuma makoma mai ɗorewa.","pillars":[{"letter":"S","title":"Tsaro da Aminci","summary":"Zaman lafiya, haɗin kan al’umma da rigakafin rikici.","description":"Tallafa wa tsaron al’umma ta hanyar haɗin gwiwar ƙungiyoyin sa ido, gina zaman lafiya da hanyoyin sasanta rikici tun kafin ya ɓarke.","icon":"shield"},{"letter":"H","title":"Lafiya, Ilimi da Abinci Mai Gina Jiki","summary":"Inganta lafiya da damar samun ilimi.","description":"Haɗa kai da masu ruwa da tsaki domin rage yawan yaran da ba sa makaranta, ƙarfafa wadatar abinci mai gina jiki, da inganta lafiyar mata da yara.","icon":"heart"},{"letter":"A","title":"Sauye-sauye a Fannin Noma","summary":"Tallafa wa manoma da samar da wadatar abinci.","description":"Tallafa wa manoman karkara wajen samun sabbin hanyoyin noma, rance mai sauƙi da shawarwarin ƙwararrun aikin gona.","icon":"sprout"},{"letter":"R","title":"Wakilci","summary":"Bayyana murya, yin dokoki da ɗaukar nauyi.","description":"Wakiltar bukatun mazaba ta hanyar gabatar da kudurori, shawarwarin dokoki, sa ido kan ayyukan gwamnati da bayar da gudummawa a muhawarar ƙasa.","icon":"landmark"},{"letter":"E","title":"Ƙarfafa Tattalin Arziki da Shigar Mata","summary":"Samar da dama ga mata, matasa da masu sana’o’i.","description":"Ƙarfafa tattalin arzikin mata da shirye-shiryen horas da matasa a fasahar AI, tsaron yanar gizo, nazarin bayanai, zane-zane, ƙera manhajoji da sauran ƙwarewar zamani.","icon":"users"},{"letter":"S","title":"Makoma Mai Tabbaci","summary":"Ci gaba mai ɗorewa da damar inganta rayuwa.","description":"Neman haɗin gwiwa wajen ƙarfafa al’umma da aiwatar da ayyukan ci gaba masu amfani waɗanda za su inganta jin daɗin jama’a da hanyoyin samun abin rayuwa.","icon":"target"}],"note":"Wannan tsari yana bayyana manufofi da shawarwari, ba tabbacin sakamako ba. Aiwatarwa tana dogara da dokoki, haɗin gwiwa, kasafin kuɗi da hukumomin gwamnati."},"digits":{"eyebrow":"SODANGI DIGITs","title":"Horar da Fasahar Dijital da Zuba Jari a Matakin Al’umma","intro":"Shirin da aka gabatar na horas da matasa bisa tsarin mazabu, domin koyar da ƙwarewar dijital da ƙarfafa kirkire-kirkire a matakin al’umma.","status":"Shiri ne da aka gabatar — ba a buɗe rajista ba tukuna","skills":["Tallace-tallacen dijital","Gyaran kayan fasaha","Gudanar da bayanai","Zane-zanen kwamfuta","Kasuwanci ta intanet"],"benefits":["Cikakken tallafin horaswa ga waɗanda aka zaɓa","Shirin samar da kayan aikin dijital da intanet ga waɗanda suka kammala bisa sharuɗɗa","Jagoranci da cibiyoyin koyo a matakin mazabu"],"footerNote":"Za a sanar da sharuɗɗan zaɓe, yadda za a samu kuɗi, ranakun shiri da bayanan rajista idan an amince da su a hukumance."},"contact":{"heading":"Tuntuɓi ƙungiyar yaɗa bayanai","intro":"Domin samun labaran hukuma, bayanan shirye-shirye da tambayoyin manema labarai, yi amfani da hanyoyin tuntuɓar da aka tantance."},"newsletter":{"title":"Ku ci gaba da samun labaran Bauchi","subtitle":"Ku karɓi labarai, sabunta manufofi da sanarwar shirye-shirye ta imel. Kuna iya dakatar da karɓa a kowane lokaci.","popupTitle":"Ku ci gaba da kasancewa tare da mu","popupBody":"Yi rajista domin karɓar mahimman labarai game da manufofi, shirye-shirye da sabbin abubuwa."},"footer":{"tagline":"Bayanin jama’a, alkawuran da aka bayyana da bibiyar ci gaban da aka tabbatar.","credit":"Dandalin Bayanan SODANGI 2027"},"audio":{"title":"SODANGI 2027 — Waƙar shafin"}}},"audio":{"enabled":false,"title":"SODANGI 2027 — Background music","url":"","autoplay":true,"loop":true}}');

-- Initial public newsroom seed entries from the supplied starter.
INSERT OR IGNORE INTO content(id,kind,title,excerpt,body,image,url,platform,media_type,status,published_at) VALUES('intro-digits-2027','news','SODANGI DIGITs: proposed ward-based digital skills programme','Programme overview: a proposed 120-person pioneer cohort across 12 wards.','The SODANGI DIGITs proposal describes intensive digital skills training for 10 selected young people from each of 12 wards in Bauchi Local Government Area. The proposed programme includes practical training, tools and connectivity support for qualifying participants, and mentorship through community learning hubs.

This is a programme proposal. Applications, funding, eligibility criteria and recruitment dates are not yet confirmed.','/assets/shares.jpg','','website','post','published','2026-11-17T12:00:00Z');
INSERT OR IGNORE INTO content(id,kind,title,excerpt,body,image,url,platform,media_type,status,published_at) VALUES('shares-framework-2027','news','Understanding the six pillars of the SHARES Agenda','Security, health and education, agriculture, representation, empowerment and secured futures.','Candidate-supplied campaign materials outline six policy priorities under the acronym SHARES: Security and Safety; Health, Education and Nutrition; Agricultural Transformation; Representation; Empowerment and Gender Inclusion; and Secured Futures.

The agenda contains aspirations and policy proposals. Delivery would require legislative action, public-sector coordination, financing and accountable implementation.','/assets/share0s.jpg','','website','post','published','2026-11-17T12:00:00Z');
INSERT OR IGNORE INTO content(id,kind,title,excerpt,body,image,url,platform,media_type,status,published_at) VALUES('biography-overview-2027','news','Biography and professional career of Adam Chindo Sodangi','An overview of the candidate-supplied biography and seven listed leadership roles.','The supplied biography describes Adam Chindo Sodangi as a political scientist and civil society advocate with more than two decades of experience. It lists seven leadership and representation roles between 2010 and 2026 involving public health, nutrition, governance and civil society.

The claims are drawn from the candidate''s supplied material and should be corroborated with appointment letters, organisational records and other supporting documents.','/assets/sodangi.jpg','','website','post','published','2026-11-17T12:00:00Z');


-- Apply once to an existing D1 database before deploying bilingual frontend.
CREATE TABLE IF NOT EXISTS content_translations (content_id TEXT NOT NULL, lang TEXT NOT NULL CHECK(lang IN ('ha')), title TEXT NOT NULL, excerpt TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(content_id,lang), FOREIGN KEY(content_id) REFERENCES content(id) ON DELETE CASCADE);
INSERT OR IGNORE INTO content_translations(content_id,lang,title,excerpt,body) VALUES ('intro-digits-2027','ha','SODANGI DIGITs: shirin horas da ƙwarewar dijital a mazabu','Shirin horas da matasa 120 da aka gabatar, tare da ba da gurabe goma ga kowace daga cikin mazabu 12.','SODANGI DIGITs shiri ne da aka gabatar domin horas da matasa a ƙwarewar zamani, ta hanyar zaɓar mutane goma daga kowace mazaba cikin mazabu 12 na yankin Bauchi. Jimillar mutanen da aka tsara ta kai 120.

Ƙwarewar da aka tsara ta haɗa da tallace-tallacen dijital, gyaran kayan fasaha, sarrafa bayanai, zane-zanen kwamfuta da kasuwanci ta intanet. An kuma gabatar da shirin kayan aiki da haɗin intanet ga waɗanda suka kammala bisa sharuɗɗa.

Wannan shawara ce, ba sanarwar buɗe rajista ba. Ba a tabbatar da kuɗaɗe, sharuɗɗan shiga ko ranakun ɗaukar masu shiga ba tukuna.');
INSERT OR IGNORE INTO content_translations(content_id,lang,title,excerpt,body) VALUES ('shares-framework-2027','ha','Fahimtar ginshikai shida na Tsarin SHARES','Tsaro, lafiya da ilimi, noma, wakilci, ƙarfafawa da makoma mai ɗorewa.','Bayanan da ɗan takara ya bayar sun bayyana ginshikai shida a ƙarƙashin SHARES: Tsaro da Aminci; Lafiya, Ilimi da Abinci Mai Gina Jiki; Sauye-sauye a Noma; Wakilci; Ƙarfafawa da Shigar Mata; da Makoma Mai Tabbaci.

Waɗannan manufofi ne da shawarwarin aiki. Aiwatar da su tana bukatar dokoki, haɗin gwiwar hukumomi, kuɗaɗe da gudanarwa mai ɗaukar nauyi.');
INSERT OR IGNORE INTO content_translations(content_id,lang,title,excerpt,body) VALUES ('biography-overview-2027','ha','Tarihin rayuwa da sana’ar Adam Chindo Sodangi','Taƙaitaccen bayanin tarihin da ɗan takarar ya bayar, wanda ya jero muhimman matsayai bakwai na shugabanci.','Bisa tarihin da aka bayar, Adam Chindo Sodangi masanin kimiyyar siyasa ne kuma mai fafutukar ƙungiyoyin farar hula da gogewar fiye da shekaru ashirin. Tarihin ya jero matsayai bakwai na shugabanci da wakilci tsakanin 2010 da 2026 a fannoni kamar lafiya, abinci mai gina jiki, shugabanci da ayyukan ƙungiyoyin farar hula.

An samo waɗannan bayanai ne daga takardun ɗan takarar. Ya kamata a tabbatar da su ta hanyar wasiƙun naɗi, bayanan ƙungiyoyi da wasu takardun hujja.');
